 proof.model=model.calculateDydxConditionalLevels(snapshot,{crypto_assets:assets});assert.ok(proof.model.levels.length>0,'NO_USEFUL_VERIFIED_CONDITIONAL_LEVEL_IN_EXACT_ACCOUNT_SAMPLE');proof.same_run_second_asset=await collect({contract:'ETH-USDT',run_id,deadline_ts:deadline});assert.equal(proof.same_run_second_asset.requests,0);proof.scoped_consumers=[];
 for(const asset of new Set(proof.model.levels.map(l=>l.asset))){const contract=asset+'-USDT',observed_ts=Date.now(),normalized=dydx.normalizeDydxPinnedLevels({snapshot,contract,run_id,observed_ts,crypto_assets:assets});if(!normalized)continue;const acquisition=scoped.createScopedProviderAcquisition({contract,native_symbol:asset,run_id,acquisition_id:run_id+':'+contract,provider:normalized.provider,venue:normalized.venue,price_quote:normalized.price_quote,collection_started_ts:snapshot.receipts[0].started_ts,collection_completed_ts:Math.max(...snapshot.receipts.map(r=>r.received_ts)),normalized_receipts:[normalized],transport_receipts:snapshot.receipts}),bound=scoped.bindScopedProviderAcquisition(acquisition,{contract,run_id,snapshot_id:run_id+':SOURCE_ONLY:'+contract,observed_ts}),view=panel.buildDynamicLiquidationPanel({contexts:[bound],reference_price:normalized.zones[0].native_reference_price,observed_ts});proof.scoped_consumers.push({contract,observed_ts,normalized,acquisition,bound,native_reference_panel:view,reference_is_native_source_not_htx_execution_price:true,MAIN:0,Telegram:0});}
 proof.structural_save={status:saved?.status??'NOT_SAVED',accounts:saved?.accounts??null,levels_saved:false};if(saved?.status!=='DYDX_STRUCTURAL_ROUTING_SAVED')throw Error('DURABLE_STRUCTURAL_ROUTING_NOT_SAVED');const readback=await dydx.loadDydxRouting({db,now:Date.now(),db_admit:within});assert.equal(readback?.routing_fingerprint,routing?.routing_fingerprint);proof.structural_readback={fingerprint:readback.routing_fingerprint,accounts:readback.accounts,next_cursor_retained:Boolean(readback.next_page_key_hex),level_or_account_balance_state_stored:false};
 if((await within({rows_read:3,rows_written:0})).allowed!==true)throw Error('MONTHLY_READBACK_NOT_ADMITTED');proof.monthly_readback=await db.prepare('SELECT scope_id,provider,unit,allowance_units,used_units,version FROM report2_liq_source_allowance_shadow WHERE scope_id=?1 LIMIT 1').bind(setup.bindings.DYDX_RPC.scope_id).first();assert.equal(proof.monthly_readback.unit,'REQUEST');assert.equal(proof.monthly_readback.allowance_units,1000);assert.ok(proof.monthly_readback.used_units>=6);assert.equal(budget.summary().actual_http,3);assert.equal(db.usageSnapshot().unknown_ops,0);proof.status='ACTUAL_PINNED_NATIVE_INPUT_TO_SCOPED_CONTEXT_AND_DURABLE_ROUTING_VERIFIED';
